 for(const s of sections){assert(s.body.length>=3&&s.table.rows.length>=3&&s.examples.length&&s.checks.length);assert(lesson.activities['topic-practice'].questions.filter(q=>q.topic===s.practiceTopic).length>=6);}
 const questionBanks=Object.values(lesson.activities).filter(a=>a.questions);
 const ids=new Set();for(const bank of questionBanks){assert.equal(new Set(bank.questions.map(q=>q.prompt)).size,bank.questions.length);for(const q of bank.questions){assert(!ids.has(q.id));ids.add(q.id);assert.equal(q.choices.length,4);assert.equal(new Set(q.choices.map(c=>c.text)).size,4);assert.equal(q.choices.filter(c=>c.correct).length,1);assert(q.explanation&&q.choices.every(c=>c.feedback));}}
 fs.writeFileSync(path.join(root,`content/lessons/lesson-${n}.json`),JSON.stringify(lesson,null,2)+'\n');
 console.log(JSON.stringify({lesson:n,paragraphs:lesson.reading.paragraphs.length,vocabulary:allVocab.length,requiredVocabulary:required.length,sections:sections.length,topicQuestions:lesson.activities['topic-practice'].questions.length,grammarQuestions:lesson.activities['grammar-exercises'].questions.length,quiz:30}));
